-- Create tables
CREATE TABLE public.products (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    name character varying NOT NULL,
    description text,
    base_price real NOT NULL DEFAULT '0'::real,
    stock integer NOT NULL DEFAULT 0,
    category character varying,
    CONSTRAINT products_pkey PRIMARY KEY (id)
);

CREATE TABLE public.price_lists (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    name character varying NOT NULL,
    prices_include_vat boolean NOT NULL DEFAULT true,
    CONSTRAINT price_lists_pkey PRIMARY KEY (id),
    CONSTRAINT price_lists_name_key UNIQUE (name)
);

CREATE TABLE public.price_list_items (
    price_list_id uuid NOT NULL,
    product_id uuid NOT NULL,
    price real NOT NULL,
    volume_price real,
    CONSTRAINT price_list_items_pkey PRIMARY KEY (price_list_id, product_id),
    CONSTRAINT fk_price_list FOREIGN KEY (price_list_id) REFERENCES public.price_lists (id) ON DELETE CASCADE,
    CONSTRAINT fk_product FOREIGN KEY (product_id) REFERENCES public.products (id) ON DELETE CASCADE
);

CREATE TABLE public.promotions (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    name character varying NOT NULL,
    description text,
    rules jsonb NOT NULL,
    CONSTRAINT promotions_pkey PRIMARY KEY (id)
);

CREATE TABLE public.agreements (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    agreement_name character varying NOT NULL,
    client_type client_type_enum NOT NULL,
    price_list_id uuid,
    CONSTRAINT agreements_pkey PRIMARY KEY (id),
    CONSTRAINT agreements_agreement_name_key UNIQUE (agreement_name),
    CONSTRAINT fk_price_list FOREIGN KEY (price_list_id) REFERENCES public.price_lists (id) ON DELETE SET NULL
);

CREATE TABLE public.agreement_promotions (
    agreement_id uuid NOT NULL,
    promotion_id uuid NOT NULL,
    CONSTRAINT agreement_promotions_pkey PRIMARY KEY (agreement_id, promotion_id),
    CONSTRAINT fk_agreement FOREIGN KEY (agreement_id) REFERENCES public.agreements (id) ON DELETE CASCADE,
    CONSTRAINT fk_promotion FOREIGN KEY (promotion_id) REFERENCES public.promotions (id) ON DELETE CASCADE
);

CREATE TABLE public.clients (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    cuit character varying,
    contact_name character varying,
    contact_dni character varying,
    address character varying,
    delivery_window character varying,
    email character varying,
    instagram character varying,
    status client_status NOT NULL DEFAULT 'pending_onboarding',
    onboarding_token uuid NOT NULL DEFAULT gen_random_uuid(),
    agreement_id uuid,
    CONSTRAINT clients_pkey PRIMARY KEY (id),
    CONSTRAINT clients_onboarding_token_key UNIQUE (onboarding_token),
    CONSTRAINT clients_cuit_key UNIQUE (cuit),
    CONSTRAINT clients_email_key UNIQUE (email),
    CONSTRAINT fk_agreement FOREIGN KEY (agreement_id) REFERENCES public.agreements (id) ON DELETE SET NULL
);

CREATE TABLE public.orders (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    client_id uuid NOT NULL,
    agreement_id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    total_amount real NOT NULL,
    status order_status NOT NULL DEFAULT 'pending',
    client_name_cache character varying NOT NULL,
    CONSTRAINT orders_pkey PRIMARY KEY (id),
    CONSTRAINT fk_client FOREIGN KEY (client_id) REFERENCES public.clients(id) ON DELETE RESTRICT,
    CONSTRAINT fk_agreement FOREIGN KEY (agreement_id) REFERENCES public.agreements(id) ON DELETE RESTRICT
);

CREATE TABLE public.order_items (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    order_id uuid NOT NULL,
    product_id uuid NOT NULL,
    quantity integer NOT NULL,
    price_per_unit real NOT NULL,
    CONSTRAINT order_items_pkey PRIMARY KEY (id),
    CONSTRAINT fk_order FOREIGN KEY (order_id) REFERENCES public.orders(id) ON DELETE CASCADE,
    CONSTRAINT fk_product FOREIGN KEY (product_id) REFERENCES public.products(id) ON DELETE RESTRICT
);

