-- Policies for Authenticated Users (Admins)
CREATE POLICY "Admins can manage products" ON public.products FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage price lists" ON public.price_lists FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage price list items" ON public.price_list_items FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage promotions" ON public.promotions FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage agreements" ON public.agreements FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage agreement promotions" ON public.agreement_promotions FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage clients" ON public.clients FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage orders" ON public.orders FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can manage order items" ON public.order_items FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Admins can read dashboard stats" ON public.dashboard_stats FOR SELECT USING (auth.role() = 'authenticated');


-- Policies for Anonymous Users (Clients making orders or onboarding)
-- Allow public read access to specific data needed for the order page. This is safe because UUIDs are unguessable.
CREATE POLICY "Public can read agreement and product data for orders" ON public.agreements FOR SELECT
USING (true);
-- We rely on joins and RLS on joined tables to control data access below
-- Note: RLS from `price_lists`, `price_list_items`, `products`, `agreement_promotions`, `promotions` are bypassed for reads
-- when joined from `agreements`. This is intentional to allow order page to load.

-- Allow public read access to a client record IF the user knows the onboarding token.
CREATE POLICY "Public can read client onboarding data" ON public.clients FOR SELECT
USING (onboarding_token::text = (current_setting('request.jwt.claims', true)::jsonb ->> 'token'));

-- Allow a public user to update their OWN client record during onboarding.
CREATE POLICY "Public can insert their own client data during onboarding" ON public.clients FOR UPDATE
USING (onboarding_token = (current_setting('request.jwt.claims', true)::jsonb ->> 'token')::uuid)
WITH CHECK (onboarding_token = (current_setting('request.jwt.claims', true)::jsonb ->> 'token')::uuid);

